style.css:
@-moz-document domain("fictionlab.ai") {
html {
    background: #000 !important;  /* fallback color */
    position: relative;
    overflow: hidden;
  }

  body {
    position: relative;
    z-index: 1;
  }

  html::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -10;
    pointer-events: none;
    overflow: hidden;
  }

  html::before {
    content: '<video autoplay loop muted playsinline src="https://example.com/your-video.mp4"></video>';
    white-space: pre;
    display: block;
    width: 100vw;
    height: 100vh;
  }

  video {
    width: 100%;
    height: 100%;
    object-fit: cover;   /* change to 'contain' for no cropping */
    object-position: center;
  }
}
